import { useState } from 'react'

import { Box, Grid, type Theme, Typography, useMediaQuery } from '@mui/material'

import NavigationArrows from 'src/components/NavigationArrows'
import RecruitNoticePreview from 'src/components/RecruitNoticePreview'
import SuspenseLoader from 'src/components/SuspenseLoader'

import { useGetRecentRecruits } from 'src/hooks/api/search'

const RecruitingClubs: React.FC<{ theme: Theme }> = ({ theme }) => {
  const [currentPage, setCurrentPage] = useState(0)

  const { data: recruits, isLoading } = useGetRecentRecruits(12)

  // 화면 크기에 따라 itemsPerPage 계산
  const isSm = useMediaQuery(theme.breakpoints.down('md')) // < 960px
  const itemsPerPage = isSm ? 1 : 2

  const totalPages = Math.ceil((recruits?.length ?? 0) / itemsPerPage)
  const startIndex = currentPage * itemsPerPage
  const endIndex = startIndex + itemsPerPage
  const currentRecruits = recruits?.slice(startIndex, endIndex) ?? []

  const handlePrevPage = () => {
    setCurrentPage(prev => (prev > 0 ? prev - 1 : totalPages - 1))
  }

  const handleNextPage = () => {
    setCurrentPage(prev => (prev < totalPages - 1 ? prev + 1 : 0))
  }

  if (isLoading) {
    return <SuspenseLoader />
  }

  if (!recruits || recruits.length === 0) {
    return null
  }

  return (
    <Box
      component="section"
      sx={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: theme.spacing(3, 0),
        padding: theme.spacing(5, 4),
        [theme.breakpoints.down('sm')]: {
          padding: theme.spacing(3, 2)
        }
      }}
    >
      {/* 헤더 섹션 */}
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          width: '100%',
          maxWidth: '1220px'
        }}
      >
        <Box>
          <Typography
            variant="h3"
            sx={{
              fontWeight: 700,
              color: 'text.primary',
              marginBottom: theme.spacing(1)
            }}
          >
            추천 모집 공고
          </Typography>
          <Typography
            variant="body1"
            sx={{
              color: 'text.secondary'
            }}
          >
            지금 새로운 부원을 찾고 있는 동아리들의 공고를 살펴보세요
          </Typography>
        </Box>

        {/* 네비게이션 화살표 */}
        <NavigationArrows onPrevClick={handlePrevPage} onNextClick={handleNextPage} visible={totalPages > 1} />
      </Box>

      {/* 카드 그리드 */}
      <Box sx={{ width: '100%', maxWidth: '1220px' }}>
        <Grid container spacing={3}>
          {currentRecruits.map((recruit, index) => (
            <Grid item xs={12} sm={12} md={6} key={`${recruit.id}-${index}`}>
              <RecruitNoticePreview recruit={recruit} />
            </Grid>
          ))}
        </Grid>
      </Box>
    </Box>
  )
}

export default RecruitingClubs
